def build():
    out = []
    ids = set()
    for i, pt, ch, t, k, ex in P:
        assert k in ("T", "N") and pt in (1, 2, 3) and i not in ids, i
        ids.add(i)
        out.append({"id": i, "s": "P", "p": pt, "ch": ch, "t": t, "k": k, "ex": ex})
    for i, pt, ch, t, a, k, ex in S:
        assert k in ("A", "B", "C") and len(a) == 3 and pt in (1, 2, 3) and i not in ids, i
        ids.add(i)
        # Stała (powtarzalna) permutacja odpowiedzi, żeby poprawna nie była zwykle „B”.
        order = list(range(3))
        random.Random(i).shuffle(order)
        a2 = [a[j] for j in order]
        k2 = "ABC"[order.index("ABC".index(k))]
        out.append({"id": i, "s": "S", "p": pt, "ch": ch, "t": t, "a": a2, "k": k2, "ex": ex})
    return out


if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    dest = os.path.join(here, "..", "data", "pytania-wlasne.json")
    data = {
        "meta": {
            "nazwa": "Pytania autorskie z objaśnieniami",
            "opis": "Zestaw do nauki przepisów przygotowany na podstawie Prawa o ruchu drogowym. To nie są pytania z oficjalnej bazy egzaminacyjnej.",
            "oficjalna": False,
        },
        "q": build(),
    }
    with open(dest, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
    p = sum(1 for q in data["q"] if q["s"] == "P")
    print(f"Zapisano {len(data['q'])} pytań ({p} TAK/NIE, {len(data['q']) - p} ABC) -> {os.path.normpath(dest)}", file=sys.stderr)
